import React from 'react';
import { describe, it, expect, vi } from 'vitest';
import { render, screen } from '@testing-library/react';
import { useExecutionStore } from '@/lib/store';
import { templates } from '@/lib/templates';
import HomePage from '@/app/(dashboard)/home/page';

vi.mock('next/navigation', () => {
  const params = new URLSearchParams('continue=fixture_A');
  return { useSearchParams: () => params };
});
vi.mock('@/lib/i18n', () => ({ useLanguage: () => ({ language: 'en', t: (key: string) => key }) }));
vi.mock('@/lib/analytics', () => ({ trackEvent: vi.fn() }));
vi.mock('@/components/Settings', () => ({ useSettings: () => ({ settings: { providers: {} } }) }));
vi.mock('@/lib/hooks/useExecute', () => ({ useProviders: () => ({ providers: [], anyConfigured: false, fetchProviders: vi.fn() }) }));
vi.mock('@/components/home/HomeBrowseExperience', () => ({ HomeBrowseExperience: () => <div>browse</div> }));
vi.mock('@/components', () => ({
  ResultViewer: ({ execution, output }: any) => <div data-testid="view">{execution.id}|{output}</div>,
  TemplatePreviewModal: () => null,
  OnboardingTour: () => null,
}));

describe('Local source-derived Home resume contradiction', () => {
  it('binds restored A output to A even when latest current execution is B', () => {
    const template = templates.find(t => !t.isFolder && t.id === 'documentation')!;
    expect(template).toBeTruthy();
    const base = { templateId: template.id, templateName: template.name, category: template.category,
      input: {}, intent: 'synthetic only', status: 'completed' as const, createdAt: new Date('2026-10-11T00:00:00Z') };
    const a = { ...base, id: 'fixture_A', output: 'OUTPUT_A', result: 'accepted' as const };
    const b = { ...base, id: 'fixture_B', output: 'OUTPUT_B' };
    useExecutionStore.setState({ executions: [b, a], currentExecution: b });
    render(<HomePage />);
    expect(screen.getByTestId('view').textContent).toBe('fixture_A|OUTPUT_A');
  });
});

